function getSessionModel(sessionId) {
  const dbPath = getOpenCodeDatabasePath();
  const db = new Database(dbPath, { readonly: true, fileMustExist: true });

  try {
    const where = sessionId ? 'WHERE s.id = ?' : 'WHERE s.directory = ?';
    const param = sessionId || process.cwd();

    const row = db.prepare(`
      SELECT
        s.id AS sessionId,
        s.model AS model,
        s.agent AS agent,
        s.directory AS directory,
        s.time_updated AS timeUpdated,
        s.time_created AS timeCreated
      FROM session s
      ${where}
      ORDER BY COALESCE(s.time_updated, s.time_created, 0) DESC
      LIMIT 1
    `).get(param);

    if (!row) {
      return {
        sessionId: sessionId || null,
        model: null,
        source: 'opencode_db_direct',
        dbPath,
        note: sessionId
          ? 'Session ID not found.'
          : 'No OpenCode session found for current working directory.',
      };
    }

    return {
      sessionId: row.sessionId,
      model: parseModel(row.model),
      agent: row.agent || null,
      directory: row.directory || null,
