+    const timer = setTimeout(() => {
+      child.kill('SIGTERM');
+      if (!settled) {
+        settled = true;
+        reject(new Error('Claude current-model lookup timed out'));
+      }
+    }, CLAUDE_ACTIVE_MODEL_TIMEOUT_MS);
+
+    const finish = (error: Error | null, result: ProviderCurrentActiveModel | null) => {
